.ff-html{font:inherit;line-height:1.8;color:inherit;overflow-wrap:anywhere;min-width:0}.ff-html :is(h1,h2,h3,h4,h5,h6){font-family:inherit;font-weight:700;line-height:1.4;margin:0 0 16px}.ff-html h1{font-size:2em}.ff-html h2{font-size:1.5em}.ff-html h3{font-size:1.2em}.ff-html :is(p,ul,ol,dl,figure,blockquote){margin:0 0 16px}.ff-html :is(ul,ol){padding-inline-start:24px}.ff-html table{border-collapse:collapse;width:100%;margin-block:16px;font-size:inherit}.ff-html :is(th,td){padding:12px 16px;border:1px solid #e3e7ec;text-align:start}.ff-html th{font-weight:650;background:#f5f6fa}.ff-html a{color:#4f46e5;text-underline-offset:3px}.ff-html img{max-width:100%;height:auto}.ff-html>:last-child{margin-bottom:0}
